def componentsAfterRemovals(n, edges, removals):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(u, v):
        ru, rv = find(u), find(v)
        if ru == rv:
            return False
        parent[ru] = rv
        return True

    gone = set(removals)
    comps = n
    for i, (u, v) in enumerate(edges):
        if i not in gone and union(u, v):
            comps -= 1
    out = [0] * len(removals)
    for k in range(len(removals) - 1, -1, -1):
        out[k] = comps
        u, v = edges[removals[k]]
        if union(u, v):
            comps -= 1
    return out
